   ================================ */
.video-hover-play::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  background-color: rgba(var(--vh-overlay-rgb, 0,0,0), 0);
  transition: background-color .22s ease, opacity .22s ease;
  opacity: 0;

