  border-bottom-right-radius: var(--vh-overlay-radius-bottom-right);
  border-bottom-left-radius: var(--vh-overlay-radius-bottom-left);
}

/* reveal overlay on hover / focus */
.video-hover-play:hover::before,
.video-hover-play:focus::before {
  background-color: rgba(var(--vh-overlay-rgb, 0,0,0), var(--vh-overlay-opacity, 0.45));
  opacity: 1;
}

/* ================================
   BUTTON
   ================================ */
.video-hover-play::after {
  content: "Watch Demo 1:44";
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%) scale(.96);

