  transition: opacity .25s ease, transform .25s ease;
  pointer-events: none;

  background-image: url("data:image/svg+xml;utf8,\
<svg xmlns='https://www.w3.org/2000/svg' width='48' height='48' viewBox='0 0 48 48'>\
<circle cx='24' cy='24' r='22' fill='white'/>\
<polygon points='20,16 34,24 20,32' fill='%23A64DF5'/>\
</svg>");
  background-repeat: no-repeat;
  background-position: var(--vh-pad-left) center;
  background-size: var(--vh-icon-size);
  z-index: 2;
}

/* Reveal on hover */
.video-hover-play:hover::after,
.video-hover-play:focus::after {
  opacity: 1;
  transform: translate(-50%, -50%) scale(1);
