  document.addEventListener("scroll", () => {
    const elements = document.querySelectorAll(".scroll-fade-text");

    elements.forEach(el => {
      const rect = el.getBoundingClientRect();
      const windowHeight = window.innerHeight;

      // Scroll progress: 0 = top of screen, 1 = bottom
      let progress = 1 - Math.min(Math.max(rect.bottom / (windowHeight * 1.5), 0), 1);

      el.querySelectorAll("span:not(.stay-black)").forEach(span => {
        if (progress > 0.3) {
          span.classList.add("fade");
        } else {
          span.classList.remove("fade");
        }
      });
    });
  });
</script>


