  import { annotate } from "https://unpkg.com/rough-notation?module";

  document.addEventListener("DOMContentLoaded", () => {
    const el = document.getElementById("highlight-word");

    if (el) {
      const highlight = annotate(el, { 
        type: 'highlight',
        color: "rgba(166, 77, 245, 0.001)", // highlight w/ opacity control
        multiline: true,
        padding: 4
      });

      const observer = new IntersectionObserver(
        (entries, obs) => {
          entries.forEach(entry => {
            if (entry.isIntersecting) {
              setTimeout(() => {
                highlight.show();   // trigger animation with delay
              }, 800); // delay in ms
              obs.unobserve(el);
            }
          });
        },
        { threshold: 0.5 } // trigger when 50% of element is visible
      );

      observer.observe(el);
    }
  });
</script>

