<script>
  document.addEventListener("DOMContentLoaded", () => {
    // 🕒 Timing Controls
    const FADE_MS = 800;     // match CSS transition duration
    const DISPLAY_MS = 4000; // how long each stays visible before switching

    // Arrays must match in length & order
    const words = [
      "Graphic Designers",
      "Photographers",
      "3D Designers",
      "Architects",
      "Illustrators"
    ];

    const images = [
      "5-1-1.webp",
      "3-1.webp",
      "1-1.webp",
      "4-1.webp",
      "2-1.webp"
    ].map(name => `https://carbonmadeassets.b-cdn.net/wp-content/uploads/2025/09/${name}`);

    // Elements
    const wordEl = document.getElementById("rotating-word");
    const imgEl = document.getElementById("rotating-image");

    let index = 0;

    setInterval(() => {
      // ---- TEXT ----
      if (wordEl) wordEl.style.opacity = 0;

      // ---- IMAGE ----
      if (imgEl) imgEl.classList.add("exiting");

      setTimeout(() => {
        // Update index
        index = (index + 1) % words.length;

        // Update text
        if (wordEl) {
          wordEl.textContent = words[index];
          wordEl.style.opacity = 1;
        }

        // Update image
        if (imgEl) {
          imgEl.src = images[index];
          imgEl.classList.remove("exiting");
          imgEl.classList.add("entering");

          // Trigger reflow so transition applies
          void imgEl.offsetWidth;

          imgEl.classList.add("active");

          // Clean up after fade-in finishes
          setTimeout(() => {
            imgEl.classList.remove("entering", "active");
          }, FADE_MS);
        }
      }, FADE_MS); // match transition duration
    }, DISPLAY_MS); // change every 4s
  });
</script>

