<script>
function initRotatingTestimonials() {
  const el = document.querySelector("#content_ba8sehesd .font_6gnnpptj1");
  if (!el) return;

  const testimonials = [
    "Fresh, bold, and dynamic I love Carbonmade.",
    "Finally, a portfolio builder that just works.",
    "A decade in, I’m still an avid user.",
    "Somehow my work looks better on Carbonmade.",
    "The new Carbonmade version is amazing."
  ];

  let index = 0;

  function rotateTestimonial() {
    el.classList.add("exiting");
    setTimeout(() => {
      index = (index + 1) % testimonials.length;
      el.textContent = `“${testimonials[index]}”`;
      el.classList.remove("exiting");
    }, 400);
  }

  setInterval(rotateTestimonial, 3000);
}

document.addEventListener("DOMContentLoaded", function () {
  setTimeout(initRotatingTestimonials, 500);
});
</script>



<script>
(function() {
  const videoURL = "https://carbon-media.accelerator.net/00000000001/fyAMraFd7exfXenqMyeFuv;1920x_/frame(1).mp4";

  function initLightbox() {
    if (document.getElementById("videoLightbox")) return;

    const overlay = document.createElement("div");
    overlay.id = "videoLightbox";
    overlay.className = "video-lightbox-overlay";
    overlay.innerHTML = `
      <div class="video-lightbox-content">
        <video id="lightboxVideo" controls playsinline webkit-playsinline></video>
      </div>
    `;
    document.body.appendChild(overlay);

    const video = document.getElementById("lightboxVideo");

    function openLightbox() {
      video.src = videoURL;
      overlay.classList.add("active");
      document.documentElement.style.overflow = "hidden";
      document.body.style.overflow = "hidden";
      setTimeout(() => video.play().catch(()=>{}), 200);
    }

    function closeLightbox() {
      overlay.classList.remove("active");
      document.documentElement.style.overflow = "";
      document.body.style.overflow = "";
      setTimeout(() => {
        video.pause();
        video.src = "";
      }, 400);
    }

    document.addEventListener("click", e => {
      const trigger = e.target.closest(".video-lightbox-trigger");
      if (trigger) {
        e.preventDefault();
        openLightbox();
      }
    });

    overlay.addEventListener("click", e => {
      if (e.target === overlay) closeLightbox();
    });

    document.addEventListener("keydown", e => {
      if (e.key === "Escape") closeLightbox();
    });
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", initLightbox);
  } else {
    initLightbox();
  }
})();
