https://carbonmadeassets.b-cdn.net/wp-content/uploads/2025/10/HoverFinal.webp","width":2881,"height":1604,"alt":"HoverFinal","title":"HoverFinal","caption":"","sizes":{"medium":"https://carbonmadeassets.b-cdn.net/wp-content/uploads/2025/10/HoverFinal-300x167.webp","medium_large":"https://carbonmadeassets.b-cdn.net/wp-content/uploads/2025/10/HoverFinal-768x428.webp"}},"1013":{"src":"https://carbonmadeassets.b-cdn.net/wp-content/uploads/2025/10/HoverFinalTwo.webp","width":2881,"height":1604,"alt":"HoverFinalTwo","title":"HoverFinalTwo","caption":"","sizes":{"medium":"https://carbonmadeassets.b-cdn.net/wp-content/uploads/2025/10/HoverFinalTwo-300x167.webp","medium_large":"https://carbonmadeassets.b-cdn.net/wp-content/uploads/2025/10/HoverFinalTwo-768x428.webp"}}},"branding":{"custom_post_css":"/* Testimonials Highlight Effect - Start */\n\n.scroll-fade-text {\n  font-size: 2.889rem; /* your base size */\n  line-height: 2.578rem;\n  text-align: center;\n  font-weight: 700;\n  color: #000;\n}\n\n.scroll-fade-text span {\n  transition: color 0.6s ease;\n  transition-delay: 1.0s; /* \u23f1 delay before fade starts */\n}\n\n.scroll-fade-text .fade {\n  color: #B9BCC6; /* faded gray */\n}\n\n.scroll-fade-text .stay-black {\n  color: #232325 !important; /* never fades */\n}\n\n/* Disable the fade ONLY inside these two modules */\n:is(#content_conh4v07m, .content_conh4v07m, #content_e2bc9efc3, .content_e2bc9efc3)\n  .scroll-fade-text .fade {\n  opacity: 1 !important;      /* cancel hidden */\n  transform: none !important;  /* cancel movement */\n  transition: none !important; /* stop anim */\n}\n\n/* Testimonials Highlight Effect - End */\n\n/* ----------------------------------------------------------------------------------------------------------------------------- */\n\n/* Comparison Table Rounded Corners - Start  */\n\n#content-713 #column_15ab0c1b9 {\n  border-width: 0 0 0.05555555555555555rem 0;\n  border-color: #;\n  background-color: #232325;\n\n  /* Individual corner