uration;\n      video.pause();\n    });\n  }\n});\n\u003C/script\u003E\n\n\u003Cscript\u003E\ndocument.addEventListener(\"DOMContentLoaded\", function () {\n  const video = document.querySelector(\"#content_9u6f0s4vz video\");\n\n  if (video) {\n    // make sure it doesn't loop\n    video.removeAttribute(\"loop\");\n\n    video.addEventListener(\"ended\", function () {\n      // set current time to last frame and pause\n      video.currentTime = video.duration;\n      video.pause();\n    });\n  }\n});\n\u003C/script\u003E\n\n\u003Cscript\u003E\ndocument.addEventListener(\"DOMContentLoaded\", function () {\n  const video = document.querySelector(\"#content_ri8wwnlds video\");\n\n  if (video) {\n    // make sure it doesn't loop\n    video.removeAttribute(\"loop\");\n\n    video.addEventListener(\"ended\", function () {\n      // set current time to last frame and pause\n      video.currentTime = video.duration;\n      video.pause();\n    });\n  }\n});\n\u003C/script\u003E\n\n\u003Cscript type=\"module\"\u003E\n  import { annotate } from \"https://unpkg.com/rough-notation?module\";\n\n  document.addEventListener(\"DOMContentLoaded\", () =\u003E {\n    const el = document.getElementById(\"highlight-word\");\n\n    if (el) {\n      const highlight = annotate(el, { \n        type: 'highlight',\n        color: \"rgba(166, 77, 245, 0.001)\", // highlight w/ opacity control\n        multiline: true,\n        padding: 4\n      });\n\n      const observer = new IntersectionObserver(\n        (entries, obs) =\u003E {\n          entries.forEach(entry =\u003E {\n            if (entry.isIntersecting) {\n              setTimeout(() =\u003E {\n                highlight.show();   // trigger animation with delay\n              }, 800); // delay in ms\n              obs.unobserve(el);\n            }\n          });\n        },\n        { threshold: 0.5 } // trigger when 50% of element is visible\n      );\n\n      observer.observe(el);\n    }\n  });\n\u003C/script\u003E\n\n\u003Cscript 