tion\n              }, 800); // delay in ms\n              obs.unobserve(el); // only run once\n            }\n          });\n        },\n        { threshold: 0.5 } // trigger when 50% visible\n      );\n\n      observer.observe(el);\n    }\n  });\n\u003C/script\u003E\n\n\u003Cscript type=\"module\"\u003E\n  import { annotate } from \"https://unpkg.com/rough-notation?module\";\n\n  document.addEventListener(\"DOMContentLoaded\", () =\u003E {\n    const el = document.getElementById(\"highlight-compare\");\n    if (el) {\n      const highlight = annotate(el, { \n        type: \"highlight\",\n        color: \"rgba(166, 77, 245, 0.08)\", // highlight w/ opacity control\n        multiline: true,\n        padding: 4\n      });\n\n      const observer = new IntersectionObserver(\n        (entries, obs) =\u003E {\n          entries.forEach(entry =\u003E {\n            if (entry.isIntersecting) {\n              setTimeout(() =\u003E {\n                highlight.show();                  // animate highlight\n                entry.target.classList.add(\"in-view\"); // trigger text color animation\n              }, 800); // delay in ms\n              obs.unobserve(el); // only run once\n            }\n          });\n        },\n        { threshold: 0.5 } // trigger when 50% visible\n      );\n\n      observer.observe(el);\n    }\n  });\n\u003C/script\u003E\n\n\u003Cscript type=\"module\"\u003E\n  import { annotate } from \"https://unpkg.com/rough-notation?module\";\n\n  document.addEventListener(\"DOMContentLoaded\", () =\u003E {\n    const el = document.getElementById(\"highlight-years\");\n    if (el) {\n      const highlight = annotate(el, { \n        type: \"highlight\",\n        color: \"rgba(166, 77, 245, 0.12)\", // \u003C-- opacity here (0.0\u20131.0)\n        multiline: true,\n        padding: 4\n      });\n\n      const observer = new IntersectionObserver((entries, obs) =\u003E {\n        entries.forEach(entry =\u003E {\n          if (entry.isIntersecting) {\n        