003E\n\n\u003Cscript\u003E\n  document.addEventListener(\"DOMContentLoaded\", () =\u003E {\n    // \ud83d\udd52 Timing Controls\n    const FADE_MS = 800;     // match CSS transition duration\n    const DISPLAY_MS = 4000; // how long each stays visible before switching\n\n    // Arrays must match in length & order\n    const words = [\n      \"Graphic Designers\",\n      \"Photographers\",\n      \"3D Designers\",\n      \"Architects\",\n      \"Illustrators\"\n    ];\n\n    const images = [\n      \"5-1-1.webp\",\n      \"3-1.webp\",\n      \"1-1.webp\",\n      \"4-1.webp\",\n      \"2-1.webp\"\n    ].map(name =\u003E `https://carbonmadeassets.b-cdn.net/wp-content/uploads/2025/09/${name}`);\n\n    // Elements\n    const wordEl = document.getElementById(\"rotating-word\");\n    const imgEl = document.getElementById(\"rotating-image\");\n\n    let index = 0;\n\n    setInterval(() =\u003E {\n      // ---- TEXT ----\n      if (wordEl) wordEl.style.opacity = 0;\n\n      // ---- IMAGE ----\n      if (imgEl) imgEl.classList.add(\"exiting\");\n\n      setTimeout(() =\u003E {\n        // Update index\n        index = (index + 1) % words.length;\n\n        // Update text\n        if (wordEl) {\n          wordEl.textContent = words[index];\n          wordEl.style.opacity = 1;\n        }\n\n        // Update image\n        if (imgEl) {\n          imgEl.src = images[index];\n          imgEl.classList.remove(\"exiting\");\n          imgEl.classList.add(\"entering\");\n\n          // Trigger reflow so transition applies\n          void imgEl.offsetWidth;\n\n          imgEl.classList.add(\"active\");\n\n          // Clean up after fade-in finishes\n          setTimeout(() =\u003E {\n            imgEl.classList.remove(\"entering\", \"active\");\n          }, FADE_MS);\n        }\n      }, FADE_MS); // match transition duration\n    }, DISPLAY_MS); // change every 4s\n  });\n\u003C/script\u003E\n\n\u003Cscript\u003E\n(() =\u003E {\n  const SECTION_ID = \"section_szb93epaz\";\n  const IMAGES = [\n    \"https://carbonmadeassets.b-cdn.net/wp-content/uploads/2025/09/GD1.jpg\",\n    \"https://carbonmadeassets.b-cdn.net/wp-content/uploads/2025/09/PH1-1.jpg\",\n    \"https://carbonmadeassets.b-cdn.net/wp-content/uploads/2025/09/3D1.jpg\",\n    \"https://carbonmadeassets.b-cdn.net/wp-content/uploads/2025/09/AR1.jpg\",\n    \"https://carbonmadeassets.b-cdn.net/wp-content/uploads/2025/09/IL2.jpg\"\n  ];\n\n  // \ud83d\udd52 Controls\n  const FADE_MS = 800;    // fade duration (ms)\n  const DISPLAY_MS = 4000; // how long each image shows before switching (ms)\n\n  const section = document.getElementById(SECTION_ID);\n  if (!section || section.dataset.bgRotatorInit === \"1\") return;\n  section.dataset.bgRotatorInit = \"1\";\n\n  // Inject CSS with timing baked in\n  const css = `\n    #${SECTION_ID} { position: relative; overflow: hidden; }\n    #${SECTION_ID} .bgstack-${SECTION_ID} { position:absolute; inset:0; z-index:0; pointer-events:none; }\n    #${SECTION_ID} .slide-${SECTION_ID} {\n      position:absolute; inset:0;\n      background-size:cover; background-position:center;\n      opacity:0; transition:opacity ${FADE_MS}ms ease; will-change:opacity;\n    }\n    #${SECTION_ID} .slide-${SECTION_ID}.is-active { opacity:1; }\n    #${SECTION_ID} \u003E :not(.bgstack-${SECTION_ID}) { position:relative; z-index:1; }\n  `;\n  const styleTag = document.createElement(\"style\");\n  styleTag.textContent = css;\n  document.head.appendChild(styleTag);\n\n  // Two layers for crossfade\n  const stack = document.createElement(\"div\");\n  stack.className = `bgstack-${SECTION_ID}`;\n  const slideA = document.createElement(\"div\");\n  const slideB = document.createElement(\"div\");\n  slideA.className = `slide-${SECTION_ID} is-active`;\n  slideB.className = `slide-${SECTION_ID}`;\n  stack.append(slideA, slideB);\n  section.prepend(stack);\n\n  let idx = 0;\n  let showA = true;\n  slideA.style.backgroundImage = `url(${IMAGES[idx]})`;\n\n  const preload = (urls) =\u003E\n    Promise.all(urls.map(src =\u003E new Promise(res =\u003E {\n      const im = new Image();\n      im.onload = res; im.onerror = res; im.src = src;\n    })));\n\n  preload(IMAGES).then(() =\u003E {\n    setInterval(() =\u003E {\n      const next = (idx + 1) % IMAGES.length;\n      const show = showA ? slideB : slideA;\n      const hide = showA ? slideA : slideB;\n\n      show.style.backgroundImage = `url(${IMAGES[next]})`;\n\n      // Fade in new layer, fade out old\n      requestAnimationFrame(() =\u003E {\n        show.classList.add(\"is-active\");\n        hide.classList.remove(\"is-active\");\n      });\n\n      idx = next;\n      showA = !showA;\n    }, DISPLAY_MS);\n  });\n})();\n\u003C/script\u003E\n\n\u003Cscript\u003E\ndocument.addEventListener(\"DOMContentLoaded\", () =\u003E {\n  const thumbsRow = document.querySelector(\"#row_lbprigf1n\");\n  const captionsRow = document.querySelector(\"#row_x69j7a39r\");\n  if (!thumbsRow || !captionsRow) return;\n\n  if (window.matchMedia(\"(max-width: 768px)\").matches) {\n    const thumbCols = thumbsRow.querySelectorAll(\"smp-column\");\n    const captionCols = captionsRow.querySelectorAll(\"smp-column\");\n\n    const carousel = document.createElement(\"div\");\n    carousel.className = \"video-carousel\";\n\n    thumbCols.forEach((col, i) =\u003E {\n      const card = document.createElement(\"div\");\n      card.className = \"video-card\";\n\n      // Clone thumbnail block\n      const thumbWrapper = col.querySelector(\"smp-content-wrapper\");\n      if (thumbWrapper) card.appendChild(thumbWrapper.cloneNode(true));\n\n      // Clone text blocks (title + timestamp)\n      const captionWrapper = captionCols[i];\n      if (captionWrapper) {\n        const contents = captionWrapper.querySelectorAll(\"smp-content\");\n        contents.forEach(content =\u003E {\n          const clone = content.cloneNode(true);\n          card.appendChild(clone); // append FIRST so it's measurable\n\n          // Force line break if 