</style>

<script>
  document.addEventListener('DOMContentLoaded', () => {
    const ids = [
      'column_1d166a15e','column_ccb06f4b9','column_dc83f01da',
      'column_763fa2f69','column_4b849f2da','column_3615a30e4',
      'column_33d567a82','column_616da0176','column_748e9c2c3'
    ];

    const cols = ids.map(id => document.getElementById(id)).filter(Boolean);
    if (!cols.length) return;

    // Add a shared class to all cards so we can target them
    cols.forEach(c => c.classList.add('testimonial-card'));

    function activate(el) {
      document.body.classList.add('cm-dim-active');
      cols.forEach(c => c.classList.remove('cm-card-hovered'));
      el.classList.add('cm-card-hovered');
    }

    function deactivate() {
      document.body.classList.remove('cm-dim-active');
      cols.forEach(c => c.classList.remove('cm-card-hovered'));
    }

    cols.forEach(col => {
      col.addEventListener('mouseenter', () => activate(col));
      col.addEventListener('mouseleave', deactivate);
      col.addEventListener('focusin', () => activate(col));
      col.addEventListener('focusout', deactivate);
    });
  });
</script>




