  --toggle-height: 64px;
  --toggle-padding: 6px;
  --text-size: 0.9rem;
  --badge-text-size: 0.75rem;

  /* Placement: left | center | right */
  --toggle-alignment: center;
}

.jitter-toggle-wrapper{display:flex;justify-content:var(--toggle-alignment);width:100%;}

.jitter-toggle{
  position:relative;
  display:inline-flex;
  width:var(--toggle-width);
  height:var(--toggle-height);
  background:#E8EAED;
  border-radius:9999px;
  padding:var(--toggle-padding);
  font-family:'Helvetica Neue', Arial, sans-serif;
  user-select:none;
  overflow:hidden;
}

.jitter-track{
  position:relative;
  display:flex;
  gap:0;
  width:100%;
  height:100%;
  border-radius:9999px;
  z-index:2;
}

.jitter-slider{
  position:absolute;
  inset:0 auto 0 0;
  height:100%;
  background:#fff;
  border-radius:9999px;
  box-shadow:0 1px 3px rgba(0,0,0,.08);
  transition:transform .3s ease, width .3s ease;
  z-index:1;
}

.jitter-option{
  flex:1;
  display:flex;
  align-items:center;
  justify-content:center;
  padding:0 20px;
  font-size:var(--text-size);
  font-weight:500;
  color:#7d7c82;
  cursor:pointer;
  transition:color .3s ease;
  position:relative;
  z-index:3;
}
.jitter-option.selected{color:#1a1a1c;}

.jitter-badge{
  display:inline-block;
  background:#A64DF5;
  color:#ffffff;
  font-size:var(--badge-text-size);
  font-weight:600;
  padding:4px 10px;
  border-radius:999px;
  margin-left:8px;
  box-shadow:0 0 0 0px rgba(0,0,0,.08) inset;
  white-space:nowrap;
}

/* Morph transition for price & interval */
.jitter-morph {
  display: inline-block;
  transition: transform 0.25s ease, opacity 0.25s ease;
}
.jitter-morph.hide {
  opacity: 0;
  transform: translateY(10px) scale(0.9); /* slide + shrink */
}
.jitter-morph.show {
  opacity: 1;
  transform: translateY(0) scale(1);
}
</style>

<div class="jitter-toggle-wrapper">
  <div class="jitter-toggle">
    <div class="jitter-track">
      <div class="jitter-slider"></div>
      <div class="jitter-option selected" data-toggle="monthly">Monthly</div>
      <div class="jitter-option" data-toggle="yearly">
        Annually <span class="jitter-badge">Save ~20%</span>
      </div>
    </div>
  </div>
</div>

<script>
document.addEventListener("DOMContentLoaded", function(){
  const track   = document.querySelector(".jitter-track");
  const slider  = track.querySelector(".jitter-slider");
  const options = track.querySelectorAll(".jitter-option");

  // === Mapping of prices and labels ===
  const pricingMap = [
    { priceId: "content_2982c2578", monthly: "$9.99",   yearly: "$99",   labelId: "content_9c608eb47" },
    { priceId: "content_3e2317092", monthly: "$14.99",  yearly: "$149",  labelId: "content_52cf8adda" },
    { priceId: "content_2a86742e4", monthly: "$24.99",  yearly: "$249",  labelId: "content_7ebc9e9da" },
  ];

  // Helper for smooth morph
  function morphText(element, newText) {
    if (!element) return;
    element.classList.add("jitter-morph", "hide");

    setTimeout(() => {
      element.textContent = newText;
      element.classList.remove("hide");
      element.classList.add("show");
      setTimeout(() => element.classList.remove("show"), 250);
    }, 250);
  }

  function updateSlider(index){
    const opt   = options[index];
    const left  = opt.offsetLeft;
    const width = opt.offsetWidth;

    slider.style.width = width + "px";
    slider.style.transform = `translateX(${left}px)`;
    options.forEach((o,i)=>o.classList.toggle("selected", i===index));

    const isYearly = opt.dataset.toggle === "yearly";

    // === Update all prices and labels ===
    pricingMap.forEach(item => {
      const priceEl = document.getElementById(item.priceId);
      if (priceEl) {
        const span = priceEl.querySelector(".is-content span");
        if (span) morphText(span, isYearly ? item.yearly : item.monthly);
      }

      const labelEl = document.getElementById(item.labelId);
      if (labelEl) {
        const span = labelEl.querySelector(".is-content span");
        if (span) morphText(span, isYearly ? "/ Year" : "/ Month");
      }
    });
  }

  options.forEach((opt, i)=>{
    opt.addEventListener("click", ()=> updateSlider(i));
  });

  window.addEventListener("resize", ()=>{
    const i = [...options].findIndex(o=>o.classList.contains("selected"));
    if(i>=0) updateSlider(i);
  });

  updateSlider(0);
});
</script>
