		<smp-content id="content_qwviwtwy0"  data-module="code" ><div class="is-content smp-code"><script type="module">
  import { annotate } from "https://unpkg.com/rough-notation?module";

  document.addEventListener("DOMContentLoaded", () => {
    const elements = [
      { id: "highlight-word", color: "rgba(166, 77, 245, 0.12)" },  
      { id: "highlight-number", color: "rgba(166, 77, 245, 0.12)" }
    ];

    elements.forEach(item => {
      const el = document.getElementById(item.id);
      if (el) {
        const highlight = annotate(el, { 
          type: "highlight",
          color: item.color,
          multiline: true,
          padding: 4
        });

        const observer = new IntersectionObserver(
          (entries, obs) => {
            entries.forEach(entry => {
              if (entry.isIntersecting) {
                setTimeout(() => {
                  highlight.show();

                  // 🔑 Smoothly morph text color after highlight starts
                  el.style.transition = "color 0.4s ease";
                  el.style.color = "#853EC4";
                }, 800); // delay before animating
                obs.unobserve(el);
              }
            });
          },
          { threshold: 0.5 }
        );

        observer.observe(el);
      }
    });
  });
</script>
</div></smp-content></smp-content-wrapper></smp-column></smp-row></smp-container></smp-section>
