lor: #232325;\n\n  /* Individual corner radii */\n  border-top-left-radius: 18px;\n  border-top-right-radius: 18px;\n  border-bottom-right-radius: 0px;\n  border-bottom-left-radius: 0px;\n}\n\n/* Comparison Table Rounded Corners Bottom  */\n#content-899 #column_bcd48cc57 {\n  border-width: 0 0 0.05555555555555555rem 0;\n  border-color: #DCDEE3;\n  background-color: #232325;\n\n  /* Individual corner radii */\n  border-top-left-radius: 0px;\n  border-top-right-radius: 0px;\n  border-bottom-right-radius: 18px;\n  border-bottom-left-radius: 18px;\n}\n\n/* Comparison Table Rounded Corners - End  */\n\n/* ----------------------------------------------------------------------------------------------------------------------------- */\n\n/* Text Hovers Footer - Start */\n\n.text-hover,\nsmp-content.text-hover,\n.text-hover * ,\nsmp-content.text-hover * {\n  color: #8C8D90 !important;\n  transition: color .25s ease;\n}\n\n.text-hover:hover,\nsmp-content.text-hover:hover,\n.text-hover:hover * ,\nsmp-content.text-hover:hover * {\n  color: #232325 !important;\n}\n\n.text-hover {\n  color: #8C8D90 !important;\n  transition: color .25s ease;\n}\n\n.text-hover:hover {\n  color: #232325 !important;\n}\n\n/* Optional: if you want the heart to change independently */\n.text-hover .heart {\n  transition: color .25s ease;\n}\n\n.text-hover:hover .heart {\n  color: #FF4D6D !important; /* pinkish red on hover */\n}\n\n.circle-sketch-highlight{\n  position:relative;\n}\n\n/* Text Hovers Footer - End */\n\n/* ----------------------------------------------------------------------------------------------------------------------------- */\n\n/* FAQ Individual Radius Controls - Start */\n\n\u003Cstyle\u003E\n/* === Shared column styling (clip inner content) === */\n#column_050ba68af,\n#column_17e5e3e1a {\n  overflow: hidden;\n  position: relative;\n}\n\n#column_050ba68af \u003E .smp-content-wrapper,\n#column_17e5e3e1a \u003E .smp-content-wrapper {\n  border-radius: inherit;\n  overflow: hidden; /* ensures images/backgrounds get clipped */\n}\n\n/* === Default radius (for desktop & larger screens) === */\n#column_050ba68af {\n  border-top-left-radius: 18px;\n  border-top-right-radius: 0px;\n  border-bottom-right-radius: 0px;\n  border-bottom-left-radius: 18px;\n}\n\n#column_17e5e3e1a {\n  border-top-left-radius: 0px;\n  border-top-right-radius: 18px;\n  border-bottom-right-radius: 18px;\n  border-bottom-left-radius: 0px;\n}\n\n/* === Responsive overrides (\u2264 544px) === */\n@media (max-width: 544px) {\n  #column_050ba68af {\n    border-top-left-radius: 18px;\n    border-top-right-radius: 18px;\n    border-bottom-right-radius: 0px;\n    border-bottom-left-radius: 0px;\n  }\n\n  #column_17e5e3e1a {\n    border-top-left-radius: 0px;\n    border-top-right-radius: 0px;\n    border-bottom-right-radius: 18px;\n    border-bottom-left-radius: 18px;\n  }\n}\n\u003C/style\u003E\n\n/* FAQ Individual Radius Controls - End */\n\n\n/* ----------------------------------------------------------------------------------------------------------------------------- */\n\n/* Scribble Highlight Testimonials Headline - Start */\n\n.highlight-number {\n  color: #232325;\n  transition: color 0.3s ease;\n}\n\n.highlight-number.in-view {\n  color: #853EC4;\n}\n\n/* Shared highlight box adjustments (explicit control) */\n#highlight-word,\n#highlight-number,\n#highlight-signed {\n  /* padding: top | right | bottom | left */\n  padding: 12px 12px 12px 12px;\n  margin: -12px -12px -12px -12px;\n  display: inline-block;\n  overflow: visible;\n}\n\n/* Scribble Highlight Testimonials Headline - End */\n\n/* ----------------------------------------------------------------------------------------------------------------------------- */\n\n/* Dim Unselected Testimonial Cards - Start */\n\n\u003C!-- Testimonial dim-on-hover (with smooth opacity) --\u003E\n\u003Cstyle\u003E\n  :root {\n    --cm-dim-opacity: 0.25;   /* how much non-hovered cards dim (0\u20131) */\n    --cm-hover-scale: 0.00;   /* slight zoom on hovered (optional) */\n    --cm-opacity-transition: 0.35s ease; /* smooth fade */\n  }\n\n  /* Add smooth opacity transition */\n  #column_1d166a15e,\n  #column_ccb06f4b9,\n  #column_dc83f01da,\n  #column_763fa2f69,\n  #column_4b849f2da,\n  #column_3615a30e4,\n  #column_33d567a82,\n  #column_616da0176,\n  #column_748e9c2c3 {\n    transition: opacity var(--cm-opacity-transition);\n  }\n\n  @media (hover:hover) and (pointer:fine){\n    /* Dim only non-hovered columns when hovering over one */\n    body.cm-dim-active .testimonial-card:not(.cm-card-hovered) {\n      opacity: var(--cm-dim-opacity) !important;\n    }\n\n    .cm-card-hovered {\n      opacity: 1 !important;\n      transform: scale(var(--cm-hover-scale));\n    }\n  }\n\u003C/style\u003E\n\n\u003Cscript\u003E\n  document.addEventListener('DOMContentLoaded', () =\u003E {\n    const ids = [\n      'column_1d166a15e','column_ccb06f4b9','column_dc83f01da',\n      'column_763fa2f69','column_4b849f2da','column_3615a30e4',\n      'column_33d567a82','column_616da0176','column_748e9c2c3'\n    ];\n\n    const cols = ids.map(id =\u003E document.getElementById(id)).filter(Boolean);\n    if (!cols.length) return;\n\n    // Add a shared class to all cards so we can target them\n    cols.forEach(c =\u003E c.classList.add('testimonial-card'));\n\n    function activate(el) {\n      document.body.classList.add('cm-dim-active');\n      cols.forEach(c =\u003E c.classList.remove('cm-card-hovered'));\n      el.classList.add('cm-card-hovered');\n    }\n\n    function deactivate() {\n      document.body.classList.remove('cm-dim-active');\n      cols.forEach(c =\u003E c.classList.remove('cm-card-hovered'));\n    }\n\n    cols.forEach(col =\u003E {\n      col.addEventListener('mouseenter', () =\u003E activate(col));\n      col.addEventListener('mouseleave', deactivate);\n      col.addEventListener('focusin', () =\u003E activate(col));\n      col.addEventListener('focusout', deactivate);\n    });\n  });\n\u003C/scrip