import { annotate } from "https://unpkg.com/rough-notation?module";

document.addEventListener("DOMContentLoaded", () => {
  const el1 = document.getElementById("highlight-line-1");
  const el2 = document.getElementById("highlight-line-2");

  if (el1 && el2) {
    const highlight1 = annotate(el1, {
      type: "highlight",
      color: "rgba(166, 77, 245, 0.11)",
      multiline: false, // single line highlight
      padding: 4
    });

    const highlight2 = annotate(el2, {
      type: "highlight",
      color: "rgba(166, 77, 245, 0.11)",
      multiline: false,
      padding: 4
    });

    const observer = new IntersectionObserver(
      (entries, obs) => {
        entries.forEach(entry => {
          if (entry.isIntersecting) {
            // Animate first line
            setTimeout(() => {
              highlight1.show();
              el1.classList.add("in-view");
            }, 600);

            // Animate second line after a short delay
            setTimeout(() => {
              highlight2.show();
              el2.classList.add("in-view");
            }, 1200);

            obs.unobserve(entry.target);
          }
        });
      },
      { threshold: 0.5 }
    );

    observer.observe(el1);
  }
});
</script>
</div></smp-content></smp-content-wrapper></smp-column></smp-row></smp-container></smp-section>
